python - <<'PY'
import cv2,numpy as np
from scipy.ndimage import distance_transform_edt
T=cv2.imread('/app/target.png',0)<155
sh=[]
for i in range(6):
 d=np.load(f'/tmp/stroke_mask{i}.npz');m=d['mask'];b=d['bbox'];print(i,m.shape,b,m.min(),m.max(),np.sum(m>=128));
 full=np.zeros((1024,1024),np.uint8);r,c=map(int,b);full[r:r+m.shape[0],c:c+m.shape[1]]=m
 sh.append(full>=128)

def shifted(a,dr,dc):
 out=np.zeros_like(a); r0=max(0,dr);r1=min(1024,1024+dr); c0=max(0,dc);c1=min(1024,1024+dc)
 out[r0:r1,c0:c1]=a[r0-dr:r1-dr,c0-dc:c1-dc]
 return out

def score(masks):
 A=np.logical_or.reduce(masks); inter=np.sum(A&T); union=np.sum(A|T);return inter/union,inter/A.sum(),inter/T.sum(),A.sum()
print('start',score(sh))
# Coordinate descent translation each stroke up to 15 px, evaluate after best whole-image registration within +/-22px.
for it in range(3):
 for i in range(6):
  best=None
  for dr in range(-15,16):
   for dc in range(-15,16):
    x=sh.copy();x[i]=shifted(sh[i],dr,dc); un=np.logical_or.reduce(x)
    # score after unrestricted 5mm register shift
    val=(-1,None)
    for tr in range(-22,23,2):
     for tc in range(-22,23,2):
      shifted_union=shifted(un,tr,tc); z=score([shifted_union]);
      if best is None or z[0]>best[0]:best=(z[0],dr,dc,tr,tc,z)
  sh[i]=shifted(sh[i],best[1],best[2]); print('it',it,'stroke',i,'shift',best[1:5],'score',best[0], 'detail',best[5])
 print('iter score',score(sh))
PY

