from scipy.sparse import csr_matrix
from scipy.sparse.csgraph import dijkstra
sys.path.insert(0,'/app/output');import gen
im=cv2.cvtColor(cv2.imread('/app/target.png'),cv2.COLOR_BGR2RGB)
mask=im.mean(2)<155;sk=gen.thin(mask); yy,xx=np.where(sk); ids={(int(y),int(x)):i for i,(y,x) in enumerate(zip(yy,xx))}
rr=[];cc=[];ww=[]
for i,(y,x) in enumerate(zip(yy,xx)):
 for dy in (-1,0,1):
  for dx in (-1,0,1):
   if not(dx or dy):continue
   j=ids.get((int(y+dy),int(x+dx)))
   if j is None:continue
   if dx and dy and ((int(y),int(x+dx)) in ids or (int(y+dy),int(x)) in ids):continue
   rr.append(i);cc.append(j);ww.append(np.hypot(dx,dy))
g=csr_matrix((ww,(rr,cc)),shape=(len(yy),len(yy)));deg=np.diff(g.indptr);ends=list(np.where(deg==1)[0]);
# paths and their pixel-node union, shortest paths for all endpoint pairs
D,P=dijkstra(g,directed=False,indices=ends,return_predecessors=True)
paths={};
for ai,a in enumerate(ends):
 for bi,b in enumerate(ends):
  if bi<=ai:continue
  q=[b]
  while q[-1]!=a:q.append(int(P[ai,q[-1]]))
  paths[(ai,bi)]=q
allnodes=set(range(len(yy)))
# enumerate perfect matching score union nodes, summed path length
best=[]
def rec(rem,pairs):
 if not rem:
  nodes=set(); cost=0
  for a,b in pairs:nodes.update(paths[a,b]);cost+=D[a,ends.index(ends[b])] if False else np.sum(g[paths[a,b][:-1],paths[a,b][1:]].A.ravel())
  best.append((len(nodes),cost,pairs.copy()))
  return
 a=rem[0]
 for j in range(1,len(rem)):
  b=rem[j];rec(rem[1:j]+rem[j+1:],pairs+[(a,b)])
rec(list(range(10)),[])
best.sort(key=lambda x:(-x[0],x[1]))
for x in best[:20]: print(x[:2],x[2])
cur=[(0,5),(1,3),(2,6),(4,7),(8,9)]
print('current',next(x[:2] for x in best if set(x[2])==set(cur)))
print('end coords',[(int(xx[k]),int(yy[k])) for k in ends])
